import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {IconButton, ActionMenu, ActionList, Tooltip, Button} from '@primer/react'
import {XIcon, ShieldIcon, TriangleDownIcon} from '@primer/octicons-react'
import {ListItemTrailingBadge} from '@github-ui/list-view/ListItemTrailingBadge'
import {testIdProps} from '@github-ui/test-id-props'

export interface PermissionRowProps {
  title: string
  actions?: string[]
  selected?: string
  description?: string
  docsUrl?: string
  onRemove?: () => void
  requireMetadata?: boolean
  onSelect?: (action: string) => void
  listViewSize?: 'xs' | 'sm' | 'lg'
}

export function PermissionRow({
  title,
  actions,
  selected,
  description,
  docsUrl,
  onRemove,
  requireMetadata,
  onSelect,
  listViewSize,
}: PermissionRowProps) {
  const showMetadataRequired = requireMetadata && title === 'Metadata'

  return (
    <ListItem
      title={
        <ListItemTitle
          value={title}
          headingStyle={{fontSize: '14px'}}
          containerStyle={{paddingTop: 16}}
          trailingBadges={
            showMetadataRequired ? [<ListItemTrailingBadge key={0} title="Required" variant="attention" />] : undefined
          }
        />
      }
      style={{paddingLeft: 16, background: 'transparent'}}
      metadata={
        <ListItemMetadata alignment="right">
          {showMetadataRequired ? (
            <Tooltip text={`Read access required to use other repository permissions.`} direction="s">
              <Button data-testid="add-members-button" inactive size="small">
                Access: Read-only
                <TriangleDownIcon className="ml-2 mr-n1" />
              </Button>
            </Tooltip>
          ) : (
            <ActionMenu>
              <ActionMenu.Button
                size="small"
                {...testIdProps(`permissions-action-button-${title.toLowerCase().replace(/\s+/g, '-')}`)}
              >
                {listViewSize === 'lg' && <span className="color-fg-subtle mr-1">Access:</span>}
                {selected ?? actions?.[0]}
              </ActionMenu.Button>
              <ActionMenu.Overlay>
                <ActionList>
                  {actions?.map(action => (
                    <ActionList.Item
                      key={action}
                      onSelect={() => {
                        onSelect?.(action)
                      }}
                    >
                      {action}
                    </ActionList.Item>
                  ))}
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          )}
          <IconButton
            icon={showMetadataRequired ? ShieldIcon : XIcon}
            aria-label={
              showMetadataRequired ? 'Read access required to use other repository permissions' : `Remove ${title}`
            }
            variant="invisible"
            {...(!showMetadataRequired && {onClick: onRemove})}
            size="small"
          />
        </ListItemMetadata>
      }
    >
      <ListItemMainContent>
        <ListItemDescription style={{paddingBottom: 12}}>
          {description}
          {docsUrl && (
            <a href={docsUrl} className="Link--inTextBlock" target="_blank" rel="noopener noreferrer">
              Learn more.
            </a>
          )}
        </ListItemDescription>
      </ListItemMainContent>
    </ListItem>
  )
}
